class SystemState:
    def __init__(self, n):
        self.C_rem = [0.0] * n  # Remaining work for each task
        self.Omega = [0.0] * n  # Time since last release for each task

def transform_to_synchronous(task_set):
    transformed_tasks = []
    for task in task_set:
        new_task = Task(O_i=0, C_i=task.C_i, T_i=task.T_i, D_i=task.D_i + task.O_i, alpha_i=task.alpha_i)
        transformed_tasks.append(new_task)
    return transformed_tasks

def calculate_sync_cycle_bound(task_set, H):
    bound = H
    for task in task_set:
        term = max(task.D_i - task.T_i, 0) + 1
        bound *= term
    return bound

def calculate_async_simulation_interval_bound_general(task_set, H):
    bound = H
    for task in task_set:
        term = max(task.O_i + task.D_i - task.T_i, 0) + 1
        bound *= term
    return bound

class SystemPreStateWithDelay:
    def __init__(self, n):
        self.C_rem = [0.0] * n
        self.Omega = [0.0] * n
        self.r = 0  # Index of running/reloaded task (0 for idle)
        self.rem_reload = 0.0 # Remaining reload time

def is_binary_delay_system(task_set):
    for task in task_set:
        if task.alpha_i not in [0, 1]:
            return False
    return True
